const categoryNames={carry:'機内持ち込み',luggage:'スーツケース'};
function cell(value){let s=String(value);if(/^\s*[=+@\-\t\r]/.test(s)||/^'+[=+@\-\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"';}
export function exportCsv(items){return '\ufeff'+[['区分','持ち物','チェック'],...Object.entries(categoryNames).flatMap(([group,name])=>items[group].map(item=>[name,item.text,item.checked?'済':'未']))].map(row=>row.map(cell).join(',')).join('\r\n')+'\r\n';}
function parse(text){const rows=[];let row=[],value='',quoted=false,closed=false;const s=text.replace(/^\ufeff/,'');for(let i=0;i<s.length;i++){const c=s[i];if(quoted){if(c==='"'){if(s[i+1]==='"'){value+='"';i++}else{quoted=false;closed=true}}else value+=c;continue}if(c==='"'){if(value||closed)throw Error('引用符の位置が不正です');quoted=true;continue}if(c===','||c==='\n'||c==='\r'){row.push(value);value='';closed=false;if(c!==','){if(c==='\r'&&s[i+1]==='\n')i++;if(row.some(x=>x!==''))rows.push(row);row=[];}continue}if(closed)throw Error('引用符の後に文字があります');value+=c}if(quoted)throw Error('引用符が閉じられていません');if(value||row.length){row.push(value);rows.push(row)}return rows;}
export function importCsv(text){const rows=parse(text);if(rows.shift()?.join(',')!=='区分,持ち物,チェック')throw Error('CSVの見出しが違います。書き出した形式のファイルを選んでください。');if(rows.length>1000)throw Error('項目は1000件までです。');const result=[];for(const [index,row] of rows.entries()){const group=Object.keys(categoryNames).find(key=>categoryNames[key]===row[0]);let name=(row[1]??'').trim();if(/^'(?=\s*[=+@\-\t\r]|'+[=+@\-\t\r])/.test(name))name=name.slice(1);if(row.length!==3||!group||!name||name.length>80||!['済','未'].includes(row[2]))throw Error(`${index+2}行目の区分・持ち物・チェックを確認してください。`);result.push({group,text:name,checked:row[2]==='済'})}return result;}
